import { prisma } from "@/lib/prisma/client";
export const dynamic="force-dynamic";
export default async function VendorsPage(){const vendors=await prisma.vendor.findMany({include:{category:true,_count:{select:{products:true,documents:true}}},orderBy:{updatedAt:"desc"},take:50});return <main className="page"><div className="page-head"><div><div className="eyebrow">Supply network</div><h1>Vendors</h1></div></div><section className="table-card"><table><thead><tr><th>Vendor</th><th>Code</th><th>Category</th><th>Status</th><th>Products</th><th>Documents</th></tr></thead><tbody>{vendors.map(v=><tr key={v.id}><td>{v.name}</td><td>{v.vendorCode}</td><td>{v.category?.name||"—"}</td><td><span className="badge">{v.status}</span></td><td>{v._count.products}</td><td>{v._count.documents}</td></tr>)}{vendors.length===0&&<tr><td colSpan={6}>No vendors found.</td></tr>}</tbody></table></section></main>}
